from pathlib import Path
import re

p=Path('index.html')
s=p.read_text(encoding='utf-8')

new_section='''<section id="actions" class="view"><div class="top"><div><div class="brand">الإجراءات والمتابعة</div><div class="sub">تسجيل ومتابعة حتى الإغلاق</div></div><button class="btn ghost" onclick="home()">الرئيسية</button></div><div class="grid"><div class="card"><div class="title">إجراء جديد</div><div class="field"><label>نوع الإجراء</label><select id="actType"><option>نواقص</option><option>صيانة</option><option>طلب دعم</option><option>مشكلة عميل</option><option>أخرى</option></select></div><div class="field"><label>الموضوع</label><input id="actSubject"></div><div class="field"><label>وصف المطلوب</label><textarea id="actDesc"></textarea></div><div class="field"><label>تاريخ التسجيل</label><input id="actDate" type="date"></div><div class="notice ok">يُسجل الإجراء تلقائيًا بحالة: <b>قيد المتابعة</b></div><button class="btn" onclick="saveAction()">تسجيل الإجراء</button></div><div class="card"><div class="title">سجل الإجراءات</div><div class="fields"><div class="field"><label>النوع</label><select id="filterType" onchange="renderActions()"><option value="">الكل</option><option>نواقص</option><option>صيانة</option><option>طلب دعم</option><option>مشكلة عميل</option><option>أخرى</option></select></div><div class="field"><label>الحالة</label><select id="filterStatus" onchange="renderActions()"><option value="">الكل</option><option value="قيد المتابعة">قيد المتابعة</option><option value="تم التصعيد">تم التصعيد — قيد المتابعة</option><option value="مغلق">مغلق</option></select></div></div><div id="actionList"></div></div></div></section>'''

s,n=re.subn(r'<section id="actions" class="view">.*?</section>\n</main>',new_section+'\n</main>',s,count=1,flags=re.S)
assert n==1, 'actions section not found'

new_js=r'''function actionDisplayStatus(x){if(x.action_status==='مغلق')return 'مغلق';if(x.raised_to)return 'تم التصعيد — قيد المتابعة';return 'قيد المتابعة'}function openActions(){show('actions');$('actDate').value=app.calendarDate||app.date;renderActions()}function renderActions(){let t=$('filterType').value,s=$('filterStatus').value,a=app.actions.filter(x=>{if(t&&x.action_type!==t)return false;let ds=actionDisplayStatus(x);if(!s)return true;if(s==='تم التصعيد')return ds==='تم التصعيد — قيد المتابعة';return ds===s});$('actionList').innerHTML=a.map(x=>{let ds=actionDisplayStatus(x),closed=x.action_status==='مغلق';return `<div class="task"><b>${esc(x.action_type)} — ${esc(x.subject)}</b><div class="mut" style="margin-top:6px">تاريخ التسجيل: ${x.request_date} | الحالة: <b>${esc(ds)}</b></div><p><b>وصف المطلوب:</b> ${esc(x.description||'')}</p>${x.raised_to&&!closed?`<div class="notice">آخر جهة تم التصعيد لها: <b>${esc(x.raised_to)}</b></div>`:''}${closed?`<div class="notice ok"><b>تم الإغلاق</b>${x.resolution_result?`<div style="margin-top:6px">نتيجة المعالجة: ${esc(x.resolution_result)}</div>`:''}</div>`:`<div class="actions" style="justify-content:flex-start"><button class="mini" style="color:#166534;border-color:#86c99a;font-weight:700" onclick="closeAction('${x.id}')">تم الإغلاق</button><button class="mini" style="color:#725700;border-color:#d7bb74;font-weight:700" onclick="escalateAction('${x.id}')">بحاجة إلى تصعيد</button></div>`}</div>`}).join('')||'<p class="mut">لا توجد إجراءات.</p>'}function actionById(id){return app.actions.find(x=>x.id===id)}function actionUpdateBody(x,extra={}){return{id:x.id,action_type:x.action_type,subject:x.subject,description:x.description||'',request_date:x.request_date||app.date,raised_to:x.raised_to||'',action_status:x.action_status||'قيد المتابعة',last_update:x.last_update||app.date,resolution_result:x.resolution_result||'',...extra}}async function escalateAction(id){try{let x=actionById(id);if(!x)throw Error('الإجراء غير موجود');if(x.action_status==='مغلق')throw Error('الطلب مغلق');let to=prompt('الجهة المرفوع لها:',x.raised_to||'');if(to===null)return;to=to.trim();if(!to)throw Error('حدد الجهة المرفوع لها');let reason=prompt('سبب التصعيد / الملاحظة:','');if(reason===null)return;reason=reason.trim();if(!reason)throw Error('سبب التصعيد مطلوب');await api('action-save',{method:'POST',body:actionUpdateBody(x,{raised_to:to,action_status:'تم الرفع',last_update:app.calendarDate||app.date,resolution_result:'[[RAKIZA_ESCALATION]]'+reason})});await refresh();openActions();alert('تم التصعيد وبقي الطلب قيد المتابعة')}catch(e){alert(e.message)}}async function closeAction(id){try{let x=actionById(id);if(!x)throw Error('الإجراء غير موجود');let result=prompt('نتيجة المعالجة قبل إغلاق الطلب:',x.resolution_result||'');if(result===null)return;result=result.trim();if(!result)throw Error('نتيجة المعالجة مطلوبة لإغلاق الطلب');await api('action-save',{method:'POST',body:actionUpdateBody(x,{action_status:'مغلق',resolution_result:result,last_update:app.calendarDate||app.date})});await refresh();openActions();alert('تم إغلاق الطلب')}catch(e){alert(e.message)}}async function saveAction(){try{let subject=$('actSubject').value.trim(),description=$('actDesc').value.trim(),d=$('actDate').value;if(!subject)throw Error('الموضوع مطلوب');if(!description)throw Error('وصف المطلوب مطلوب');if(!d)throw Error('تاريخ التسجيل مطلوب');await api('action-save',{method:'POST',body:{action_type:$('actType').value,subject,description,request_date:d,raised_to:'',action_status:'قيد المتابعة',last_update:d,resolution_result:''}});$('actSubject').value='';$('actDesc').value='';await refresh();show('actions');$('actDate').value=app.calendarDate||app.date;$('filterType').value='';$('filterStatus').value='';renderActions();setTimeout(()=>$('actionList')?.scrollIntoView({behavior:'smooth',block:'start'}),50);alert('تم تسجيل الإجراء وتحويله إلى سجل الإجراءات بحالة قيد المتابعة')}catch(e){alert(e.message)}}load();'''

s,n=re.subn(r'function openActions\(\).*?load\(\);',new_js,s,count=1,flags=re.S)
assert n==1, 'actions javascript block not found'

p.write_text(s,encoding='utf-8')
